        {/* View Block Metrics Button */}
        <Link href={runComparisonHref(benchmarkRunId)}>
          <button
            type="button"
            className="px-4 py-2 bg-slate-100 text-slate-900 rounded hover:bg-slate-200 transition-colors flex items-center gap-2"
          >
