  // Hugs the switch rather than filling the row: with no label beside it, a
  // full-width button would hover-fill a strip of empty sidebar. The inherited
  // footer-row padding keeps the hit target at 54×38, comfortably past the 24×24
  // WCAG 2.5.8 floor even though the track itself is only 34×20.
  themeButton: {
    border: 0,
    background: 'transparent',
    cursor: 'pointer',
  },
  // The switch state and the theme are the same thing, so the off state only ever
  // renders on a light sidebar and the on state only on a dark one. Off therefore
  // has to hold up against white specifically, and a pale track left the white
  // thumb at 1.15:1 — invisible, against the 3:1 WCAG 1.4.11 asks of UI components.
  // The fix is a gray-50 track rather than an outlined thumb: it puts the thumb and
  // the track edge both at ~5:1 without ringing the icon in a second circle.
  switchTrack: {
    flexShrink: 0,
    display: 'flex',
    alignItems: 'center',
    width: 34,
    height: 20,
    padding: 2,
    borderRadius: 999,
    boxSizing: 'border-box',
  },
  switchThumb: {
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    width: 16,
    height: 16,
    borderRadius: '50%',
    // Reads against both the grey off-track and the blue on-track. On-state
    // color and travel are Tailwind `dark:` variants on the thumb, keyed off
    // `html[data-theme]` — React state lags a frame behind the pre-paint
    // script, and driving those here flashes the switch on reload.
    background: 'var(--bds-gray-0)',
  },
  main: { flex: 1, display: 'flex', flexDirection: 'column', minWidth: 0 },
  // Grow on short pages so the activity drawer can sit at the bottom; don't
  // shrink, or tall pages compress instead of letting the document scroll.
  topbar: {
    height: 65,
    flexShrink: 0,
    borderBottom: `1px solid ${SELECTED}`,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '0 28px',
  },
  topbarTitle: { fontSize: 16, fontWeight: 500 },
  content: { flexGrow: 1, flexShrink: 0, display: 'flex', flexDirection: 'column' as const, minWidth: 0 },
  contentInner: { width: '100%', maxWidth: 1280, margin: '0 auto', padding: '24px 28px 80px', flexGrow: 1, flexShrink: 0, display: 'flex', flexDirection: 'column' as const, minWidth: 0 },
};

