function NavRow({ icon, label, href, active, enabled, hasChildren, onNavigate }: NavRowProps) {
  let color = DISABLED;
  if (enabled) {
    color = active ? 'var(--bds-gray-80)' : 'var(--bds-gray-50)';
  }

  const content = (
    <>
      {icon && (
        <span style={styles.navIcon}>
          <NavGlyph name={icon} />
        </span>
      )}
      <span className={TEXT_TRIM}>{label}</span>
      {!enabled && <span style={styles.soon}>Soon</span>}
      {hasChildren && (
        <span style={{ marginLeft: 'auto', color: 'var(--bds-gray-50)' }}>
          <AnimatedArrowIcon size={16} strokeWidth={1.5} />
        </span>
      )}
    </>
  );

  const rowStyle = {
    ...styles.navRow,
    ...styles.navLink,
    color,
    cursor: enabled ? 'pointer' : 'default',
  };

  if (!enabled) {
    return <div className={NAV_LABEL} style={rowStyle}>{content}</div>;
  }

  return (
    <Link
      href={href}
      className={`${hasChildren ? 'group ' : ''}nav-row-hover${active ? ' nav-row-active' : ''} ${NAV_LABEL} ${NAV_FOCUS_RING}`}
      style={rowStyle}
      onClick={(event) => {
        if (opensInNewTab(event)) return;
        trackNavClick(label);
        onNavigate?.();
      }}
    >
      {content}
    </Link>
  );
}

/**
 * True for clicks the browser handles itself (new tab/window), which navigate
 * nothing here — so they must not move the nav's active state.
 */
function opensInNewTab(event: ReactMouseEvent): boolean {
  return event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0;
}

const slideVariants = {
  enter: ({ direction }: NavPresenceCustom) => ({ x: direction > 0 ? 10 : -10, opacity: 0, filter: 'blur(1px)' }),
  center: { x: 0, opacity: 1, filter: 'none' },
  exit: ({ direction }: NavPresenceCustom) => ({ x: direction > 0 ? -10 : 10, opacity: 0, filter: 'blur(1px)' }),
};

function useExitingHighlightPath(presentPath: string): string {
  const isPresent = useIsPresent();
  return navExitingHighlightPath(isPresent, usePresenceData(), presentPath);
}

function TopNavList({ highlightPath, onSelect }: { highlightPath: string; onSelect: (href: string) => void }) {
  const path = useExitingHighlightPath(highlightPath);
  return (
    <nav style={styles.nav}>
      {NAV_ITEMS.filter((item) => item.icon).map((item) => (
        <NavRow
          key={item.href}
          icon={item.icon}
          label={item.label}
          href={item.href}
          active={isTopNavActive(item, path)}
          enabled={item.enabled}
          hasChildren={!!item.children}
          onNavigate={() => onSelect(item.href)}
        />
      ))}
    </nav>
  );
}

const slideTransition = { duration: 0.2, ease: easeOut, x: { visualDuration: 0.2, type: 'spring', bounce: 0 } };

// How long the nav trusts a tapped href before falling back to the router. Only
// reached if a navigation never commits (aborted, failed, or a modified click that
// slipped through), so it just has to be longer than a slow route.
const PENDING_PATH_TIMEOUT_MS = 5000;

const SIDEBAR_FOOTER_LINK =
  `group outline-none ${NAV_LABEL} text-bds-gray-50 transition-colors duration-150 hover:text-bds-gray-80`;

const SIDEBAR_FOOTER_LINK_LABEL =
  'inline-flex items-center gap-2.5 rounded-lg group-focus-visible:outline group-focus-visible:outline-2 group-focus-visible:outline-offset-2 group-focus-visible:outline-brand-blue';

// Track and thumb. Shared with the `:not(...)` list in disableAnimation so the
// page-wide no-transition stamp cannot override the 180ms slide.
const THEME_SWITCH_ANIM = 'theme-switch-anim';

// Rides inside the switch thumb. Stroke is heavier than the nav glyphs' 1.8
// because at 10px that weight all but disappears. Both glyphs are in the
// tree so `dark:` (html[data-theme]) can pick the right one on first paint,
// before React hydrates the stored preference.
function ThemeIcon() {
  const common = {
    width: 10,
    height: 10,
    viewBox: '0 0 24 24',
    fill: 'none',
    stroke: 'currentColor',
    strokeWidth: 2.6,
    strokeLinecap: 'round' as const,
    strokeLinejoin: 'round' as const,
  };
  return (
    <>
      <svg {...common} className="dark:hidden">
        <circle cx="12" cy="12" r="4" />
        <path d="M12 2v2M12 20v2M4.93 4.93l1.42 1.42M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.42-1.42M17.66 6.34l1.41-1.41" />
      </svg>
      <svg {...common} className="hidden dark:block">
        <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79Z" />
      </svg>
    </>
  );
}

type SidebarContentProps = {
  dark: boolean;
  onToggleTheme: () => void;
  onNavigate?: () => void;
  hideBrand?: boolean;
};

function SidebarContent({ dark, onToggleTheme, onNavigate, hideBrand }: SidebarContentProps) {
  const pathname = usePathname() || '/';
  // The nav follows the tapped href immediately instead of waiting for the router:
  // usePathname() only updates once the route commits, which left the pill and the
  // sub-nav slide sitting still for the whole navigation — the tap felt dead, then
  // everything moved at once.
  const [pendingPath, setPendingPath] = useState<string | null>(null);
  const activePath = navHighlightPath(pendingPath, pathname);
  const activeParent = navActiveParent(pendingPath, pathname);
  const directionRef = useRef(1);
  const prevParentRef = useRef<string | null>(activeParent?.href ?? null);
  const scrollViewportRef = useRef<HTMLDivElement>(null);
  const paneKey = activeParent?.href ?? 'main';

  // Direction must update during render. An effect applies one commit late,
  // so the first click of the section back-header still slid as if going in.
  const prevParent = prevParentRef.current;
  const currParent = activeParent?.href ?? null;
  const nextDirection = navSlideDirection(prevParent, currParent);
  if (nextDirection !== null) {
    directionRef.current = nextDirection;
    prevParentRef.current = currParent;
  }

  // Any commit hands control back to the router, including a Back that lands
  // somewhere other than the tapped href.
  useEffect(() => {
    setPendingPath(null);
  }, [pathname]);

  useEffect(() => {
    // '/' is the back-header view: the route will not commit, so a timeout
    // would snap the submenu back. Only time out real pending navigations.
    if (!pendingPath || pendingPath === '/') return;
    const timer = setTimeout(() => setPendingPath(null), PENDING_PATH_TIMEOUT_MS);
    return () => clearTimeout(timer);
  }, [pendingPath]);

  // Shared scroller keeps one logo across pane swaps, so a leftover scrollTop
  // from the previous list would hide it. Jump back to the top on each swap.
  useEffect(() => {
    const viewport = scrollViewportRef.current;
    if (viewport) viewport.scrollTop = 0;
  }, [paneKey]);

  const selectPath = (href: string) => {
    setPendingPath(href);
    // Keep the drawer open when the tap is the section root (Vibenet,
    // Benchmark). getActiveParent already knows which hrefs have a submenu.
    if (getActiveParent(href)?.href !== href) onNavigate?.();
  };

  const direction = directionRef.current;
  // highlightPath rides AnimatePresence custom so the exiting root list can
  // move the pill — its React props are frozen on the previous commit.
  const presenceCustom: NavPresenceCustom = { direction, highlightPath: activePath };

  return (
    <>
      <div style={styles.navSlot}>
        <NavScrollArea viewportRef={scrollViewportRef} contentClassName={hideBrand ? 'pt-3' : undefined}>
          {!hideBrand && (
            <div style={styles.brand} className="sidebar-gutter sidebar-brand">
              <AnimatedBaseLogo size={BRAND_MARK_SIZE} />
            </div>
          )}
          <div className="sidebar-gutter">
            <AnimatePresence mode="popLayout" initial={false} custom={presenceCustom}>
              {activeParent ? (
                <motion.div
                  key={`sub-nav:${activeParent.href}`}
                  custom={presenceCustom}
                  variants={slideVariants}
                  initial="enter"
                  animate="center"
                  exit="exit"
                  transition={slideTransition}
                  className="sidebar-nav-pane"
                  style={styles.navPane}
                >
                  <Link
                    href="/"
                    className={`nav-header-hover group ${NAV_LABEL} ${NAV_FOCUS_RING}`}
                    style={{ ...styles.navLink, display: 'flex', alignItems: 'center', padding: '9px 6px 9px 2px', marginBottom: 2, color: 'var(--bds-gray-50)' }}
                    onClick={(event) => {
                      if (opensInNewTab(event)) return;
                      // Stay on the current page and keep the mobile drawer
                      // open. href="/" remains for modified clicks (new tab).
                      event.preventDefault();
                      setPendingPath('/');
                    }}
                  >
                    <svg
                      width={16}
                      height={16}
                      viewBox="0 0 20 20"
                      fill="none"
                      aria-hidden="true"
                      style={{ transform: 'scaleX(-1)', flexShrink: 0 }}
                    >
                      <path d="M7.5 4L13.5 10L7.5 16" stroke="currentColor" strokeWidth={1.5} />
                      <path
                        d="M13.5 10H0"
                        stroke="currentColor"
                        strokeWidth={1.5}
                        strokeDasharray="13.5"
                        strokeDashoffset="13.5"
                        className="transition-[stroke-dashoffset] duration-200 ease-out group-hover:[stroke-dashoffset:0]"
                      />
                    </svg>
                    <span className="flex-1 text-center pr-4">
                      <span className={TEXT_TRIM}>{activeParent.label}</span>
                    </span>
                  </Link>
                  <nav style={styles.nav}>
                    {activeParent.children!.map((child) => {
                      const active = isChildActive(child, activePath);
                      return (
                        <NavRow
                          key={child.href}
                          icon={child.icon}
                          label={child.label}
                          href={child.href}
                          active={active}
                          enabled={true}
                          onNavigate={() => selectPath(child.href)}
                        />
                      );
                    })}
                  </nav>
                </motion.div>
              ) : (
                <motion.div
                  key="main-nav"
                  custom={presenceCustom}
                  variants={slideVariants}
                  initial="enter"
                  animate="center"
                  exit="exit"
                  transition={slideTransition}
                  className="sidebar-nav-pane"
                  style={styles.navPane}
                >
                  <TopNavList highlightPath={activePath} onSelect={selectPath} />
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </NavScrollArea>
      </div>

      <div style={styles.sidebarFooter} className="sidebar-gutter">
        <a href="https://docs.base.org/base-chain/specs/upgrades/overview" target="_blank" rel="noreferrer" className={SIDEBAR_FOOTER_LINK} style={styles.footerLink}>
          <span className={SIDEBAR_FOOTER_LINK_LABEL}>
            <span style={styles.footerIcon}>
              <svg width={18} height={18} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round">
                <path d="M3 6.7C3 4.65 4.65 3 6.7 3h10.6C19.35 3 21 4.65 21 6.7v10.6c0 2.05-1.65 3.7-3.7 3.7H6.7C4.65 21 3 19.35 3 17.3V6.7Z" />
                <path d="M12.2 16.5V7.9M16.9 12.6 12.2 7.9 7.6 12.6" />
