          <span className={SIDEBAR_FOOTER_LINK_LABEL}>
            <span style={styles.footerIcon}>
              <svg width={18} height={18} viewBox="6 6 28 28" fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round">
