      // === PHASE 3: MONO CHARS APPEAR (0.5s) ===
      if (monoChars) {
        Array.from(monoChars).forEach((char, index) => {
          firstSequence.push([
            char,
            { opacity: [0, 1] },
            {
              duration: 0.03,
              at: 0.5 + index * 0.05,
