      // === PHASE 6: CHAR TRANSITIONS (1.2s) ===
      const charOrder = [2, 0, 3, 1];
      const monoStartDelay = 1.2;
      const charInterval = 0.04;

      charOrder.forEach((charIndex, orderIndex) => {
        const charTime = monoStartDelay + orderIndex * charInterval;

